get_site_settings.code:
final response = await client.siteSettings.getSiteSettings();
final siteSettings = (response.map as Map)['site_settings'] as Map;
print(siteSettings['store_details']);
print(siteSettings['brand_kit']);

patch_site_settings.code:
final response = await client.siteSettings.patchSiteSettings({
  'site_settings': {
    'brand_kit': {'palette_name': 'Autumn'},
    'date_time': {'hide_time_zone': false},
  },
});
final siteSettings = (response.map as Map)['site_settings'] as Map;
print((siteSettings['brand_kit'] as Map)['palette_name']);
print((siteSettings['date_time'] as Map)['hide_time_zone']);

